window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[248]={"id":"248","numero":248,"titre":"Prévention primaire par la nutrition","objectifs":[{"id":"248-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l'activité physique, de l'inactivité physique, de la sédentarité et de la condition physique","contenu":"<p>La <span class=\"kw-def\"><strong>nutrition</strong></span> repose sur <strong>trois dimensions</strong> indissociables : l'<span class=\"kw-clinique\">alimentation</span>, l'<span class=\"kw-clinique\">activité physique</span> et la <span class=\"kw-clinique\">sédentarité</span>. Quatre notions doivent être distinguées sans les confondre.</p>\n      <table >\n        <thead><tr><th>Notion</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Activité physique</strong></span></td>\n            <td>Tout <strong>mouvement produit par les muscles squelettiques</strong> entraînant une <span class=\"kw-bio\">augmentation de la dépense énergétique au-dessus de la valeur de repos</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Inactivité physique</strong></span></td>\n            <td>Niveau d'AP insuffisant : <span class=\"kw-chiffre\">&lt; 30 min/jour</span> d'AP (modérée ou intense) au minimum <span class=\"kw-chiffre\">5×/semaine</span> chez l'adulte ; <span class=\"kw-chiffre\">&lt; 60 min/jour</span> chez l'enfant</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Sédentarité</strong></span></td>\n            <td>Comportement avec <strong>position assise ou couchée dominante</strong> à l'éveil, associé à une <span class=\"kw-bio\">dépense énergétique faible (&lt; 1,6 MET)</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Condition physique</strong></span></td>\n            <td>Capacité générale de l'organisme à <strong>réaliser les activités de la vie quotidienne sans fatigue excessive</strong> et à répondre favorablement à l'effort (endurance cardio-respiratoire, équilibre, souplesse, force, endurance et flexibilité musculaire)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Inactivité ≠ <span class=\"kw-etio\">sédentarité</span>.</strong> L'<span class=\"kw-clinique\">inactivité physique</span> est un <strong>défaut d'AP</strong> (on n'atteint pas les seuils recommandés) ; la <span class=\"kw-clinique\">sédentarité</span> est un <strong>excès de temps assis/couché</strong>. On peut être à la fois actif (AP suffisante) et sédentaire (beaucoup de temps assis par ailleurs) : ce sont deux cibles de prévention <strong>distinctes</strong>.</div>","frequence":0},{"id":"248-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition définir et expliquer les différentes modalités d'activité physique","contenu":"<p>L'activité physique se décline selon le <strong>contexte de réalisation</strong> et se quantifie par une unité métabolique de référence.</p>\n      <p><strong>Les différents types d'activité physique</strong> (selon le contexte)</p>\n      <ul>\n        <li><span class=\"kw-clinique\">AP liée aux <strong>déplacements</strong></span> (marche, vélo, montée d'escaliers…)</li>\n        <li><span class=\"kw-clinique\">AP liée à l'<strong>activité professionnelle ou scolaire</strong></span></li>\n        <li><span class=\"kw-clinique\">AP de <strong>loisirs</strong></span> (promenades, bricolage, sport encadré ou non)</li>\n        <li><span class=\"kw-clinique\">AP liée aux <strong>activités au domicile</strong></span> — <strong>jardinage</strong>, tâches ménagères, s'occuper des enfants <em>(ajout LiSA)</em></li>\n        <li><span class=\"kw-clinique\">Temps de <strong>sédentarité</strong></span> : temps quotidien passé assis ou allongé sans bouger</li>\n      </ul>\n      <p><strong>Caractérisation d'une AP</strong> — elle se définit selon <strong>4 paramètres</strong> : la <span class=\"kw-bio\">durée</span> (<strong>par séquence de <span class=\"kw-chiffre\">10 minutes minimum</span></strong> — LiSA), l'<span class=\"kw-bio\">intensité</span>, la <span class=\"kw-bio\">fréquence</span> et le <span class=\"kw-bio\">type / contexte</span> de réalisation.</p>\n      <div class=\"callout callout-info\"><strong>Le MET (Metabolic Equivalent of Task).</strong> Unité de mesure de l'intensité = <span class=\"kw-bio\">rapport de la dépense énergétique de l'activité sur le métabolisme de base</span>.\n        <ul>\n          <li><span class=\"kw-chiffre\">1 MET</span> = coût énergétique d'une personne au <strong>repos total</strong></li>\n          <li>La valeur en MET <strong>augmente avec l'intensité</strong> de l'activité</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-info\"><strong>VO₂max — reflet de la condition cardio-respiratoire (LiSA).</strong> La <span class=\"kw-def\">VO₂max</span> est la <strong>consommation maximale d'oxygène</strong> mesurée lors d'une <span class=\"kw-imagerie\">épreuve d'effort avec analyse des gaz expirés</span> (exprimée en mL/kg/min ou en équivalents MET). Elle constitue le <strong>gold standard</strong> d'évaluation de la capacité aérobie et un puissant marqueur pronostique cardiovasculaire indépendant. Un gain de <span class=\"kw-chiffre\">+1 MET</span> de VO₂max est associé à une réduction de la mortalité toutes causes de l'ordre de <span class=\"kw-chiffre\">10-25 %</span>.</div>","frequence":0},{"id":"248-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités d'évaluation du niveau d'activité physique","contenu":"<p>L'évaluation porte à la fois sur le <strong>niveau d'AP</strong> et le <strong>niveau de <span class=\"kw-etio\">sédentarité</span></strong>.</p>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Niveau de sédentarité</strong></span> : temps moyen (en minutes ou heures) passé <strong>éveillé, assis ou allongé</strong> au quotidien</li>\n        <li><span class=\"kw-clinique\"><strong>Niveau d'AP</strong></span> : apprécié sur la durée, l'intensité, la fréquence et le type des activités</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Méthode de référence.</strong> Pour évaluer les différentes dimensions de l'AP, la méthode de référence est la <span class=\"kw-bio\">calorimétrie indirecte</span> — mesure des échanges gazeux respiratoires (O₂ consommé et CO₂ produit) au repos (dépense énergétique de base), à l'exercice (dépense liée à l'AP) et lors d'une <span class=\"kw-imagerie\">épreuve d'effort</span> (<span class=\"kw-bio\">VO₂max</span>, condition cardio-respiratoire). Limite : <span class=\"kw-alerte\">mesure l'AP réalisée pendant l'examen, non l'AP habituelle</span>.</div>\n\n      <p><strong>Panorama des outils de mesure de l'AP (LiSA)</strong></p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Outil</th><th>Paramètre mesuré</th></tr></thead>\n        <tbody>\n          <tr>\n            <td rowspan=\"2\"><span class=\"kw-def\">Déclaratifs</span></td>\n            <td><span class=\"kw-clinique\">Questionnaires / carnets</span></td>\n            <td>AP (type, intensité, durée, fréquence) ; dépense énergétique déclarée</td>\n          </tr>\n          <tr>\n            <td colspan=\"2\"><em>Outils de première intention en pratique courante — dépendent de la mémoire du sujet.</em></td>\n          </tr>\n          <tr>\n            <td rowspan=\"3\"><span class=\"kw-def\">Capteurs de mouvements</span></td>\n            <td><span class=\"kw-clinique\">Podomètre</span></td>\n            <td><span class=\"kw-chiffre\">Nombre de pas</span> et distance parcourue ; outil de <strong>prise de conscience</strong> et d'atteinte d'objectifs</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Accéléromètre</span></td>\n            <td>Activité et intensité en <span class=\"kw-chiffre\">coups/min (counts)</span> ; évalue la dépense énergétique liée à l'activité</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Dispositifs GPS</span></td>\n            <td>Distance, vitesse et topographie ; dépense énergétique ; <span class=\"kw-alerte\">ne fonctionne pas à l'intérieur</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Marqueur physiologique</span></td>\n            <td><span class=\"kw-clinique\">Fréquence cardiaque</span></td>\n            <td>Activité et intensité en <span class=\"kw-chiffre\">bpm</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Facteurs associés</span></td>\n            <td><span class=\"kw-clinique\">Échelles visuelles analogiques (EVA)</span></td>\n            <td>Dyspnée d'effort, douleurs, motivation…</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 En pratique courante, l'évaluation repose surtout sur l'<strong>interrogatoire</strong> et les <strong>questionnaires</strong> — voir objectif suivant.</em></p>","frequence":0},{"id":"248-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités d'évaluation à l'entretien les différents types d'activité physique","contenu":"<p>À l'entretien, on explore systématiquement les <strong>4 types d'AP</strong> pour dresser le profil d'activité du patient et repérer une inactivité et/ou une <span class=\"kw-etio\">sédentarité</span>.</p>\n      <table >\n        <thead><tr><th>Dimension explorée</th><th>Ce que l'on recherche</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Déplacements</strong></span></td><td>Marche, vélo : durée et fréquence des trajets actifs</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Activité professionnelle / scolaire</strong></span></td><td>Métier actif ou sédentaire, temps assis au travail/à l'école</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Loisirs</strong></span></td><td>Pratique sportive, jardinage : type, intensité, fréquence</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Sédentarité</strong></span></td><td>Temps quotidien assis/allongé (dont temps d'écran)</td></tr>\n        </tbody>\n      </table>\n      <p>Pour chaque type, on précise les <strong>4 paramètres</strong> : <span class=\"kw-bio\">durée</span>, <span class=\"kw-bio\">intensité</span>, <span class=\"kw-bio\">fréquence</span>, <span class=\"kw-bio\">contexte</span>. L'entretien permet aussi d'<strong>évaluer la motivation et les freins</strong> au changement (cf. objectifs Étiologies / Prise en charge).</p>","frequence":0},{"id":"248-5","rang":"A","rubrique":"Étiologies","titre":"Connaître les principaux effets de l'activité physique et de la condition physique sur la santé en prévention primaire","contenu":"<p>L'AP est un <strong>déterminant majeur de santé</strong> en <span class=\"kw-def\">prévention primaire</span>. La relation effet/dose suit une <span class=\"kw-def\">courbe curviligne</span> : le <strong>gain est maximal lors du passage d'inactif à modérément actif</strong> (<span class=\"kw-chiffre\">30 min</span>, 5×/sem).</p>\n      <div class=\"callout callout-danger\"><strong>Un faible niveau d'AP augmente le risque de :</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Mortalité totale et cardiovasculaire</span> (davantage liée à la <strong>quantité</strong> d'AP qu'à son intensité)</li>\n          <li><span class=\"kw-def\">Morbidité</span> <span class=\"kw-clinique\">coronarienne</span></li>\n          <li><span class=\"kw-clinique\">Diabète de type 2</span> et <span class=\"kw-clinique\">HTA</span></li>\n          <li><span class=\"kw-clinique\">Cancer</span></li>\n          <li><span class=\"kw-clinique\">Prise de poids</span></li>\n          <li>Troubles psychiques : <span class=\"kw-clinique\">anxiété, dépression</span></li>\n        </ul>\n      </div>\n      <p><strong>Bénéfices de l'AP régulière</strong></p>\n      <ul>\n        <li>Prévention de l'<span class=\"kw-clinique\">obésité</span> (effet ++ chez l'enfant)</li>\n        <li>Prévention de la <span class=\"kw-clinique\">perte d'autonomie</span> : sarcopénie, ostéoporose, déclin cognitif (↓ <span class=\"kw-def\">incidence</span> Alzheimer et Parkinson)</li>\n        <li>Bénéfices psychologiques : ↓ stress, réappropriation positive du corps, développement d'un relationnel positif, soulagement des tensions, renforcement de l'humeur</li>\n      </ul>\n      <p><strong>Effets spécifiques chez l'enfant</strong></p>\n      <ul>\n        <li>Améliore la <span class=\"kw-clinique\">condition physique</span>, la composition corporelle et la <span class=\"kw-clinique\">santé osseuse</span></li>\n        <li>↓ les <span class=\"kw-def\">facteurs de risque</span> cardiovasculaires</li>\n        <li>Améliore la santé mentale : renforce confiance et estime de soi, ↓ anxiété/stress/dépression</li>\n        <li>Facteur favorable de <span class=\"kw-clinique\">réussite scolaire</span></li>\n      </ul>","frequence":0},{"id":"248-6","rang":"A","rubrique":"Étiologies","titre":"Connaître les effets de l'alimentation sur la santé","contenu":"<div class=\"callout callout-warn\"><strong>Poids de la mauvaise alimentation.</strong> La part de <span class=\"kw-alerte\">mortalité attribuable à une mauvaise alimentation</span> est estimée à <span class=\"kw-chiffre\">15 %</span> dans le monde — <strong>supérieure à celle du tabac</strong>. Soit <span class=\"kw-chiffre\">≈ 11 millions de décès/an</span> (maladies CV, cancers, <span class=\"kw-etio\">diabète</span>), c'est-à-dire <span class=\"kw-chiffre\">1 décès sur 5</span>. En cause notamment : excès de <strong>sel</strong> et apport <strong>insuffisant en fruits et légumes</strong>.</div>\n      <p><strong>Maladies métaboliques et cardiovasculaires</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Sel</span> : déterminant de la <span class=\"kw-bio\">pression artérielle</span></li>\n        <li><span class=\"kw-clinique\">AG saturés en excès</span> : hypercholestérolémie (↑ LDLc)</li>\n        <li><span class=\"kw-clinique\">Prise de poids</span> (bilan énergétique positif) : favorisée par <span class=\"kw-etio\">sédentarité</span>, boissons sucrées, fast-food, alimentation de type occidental</li>\n        <li><span class=\"kw-clinique\">Obésité</span> : FDR de syndrome métabolique, de <span class=\"kw-clinique\">DT2</span>, de cancer et de pathologies ostéo-articulaires</li>\n      </ul>\n      <p class=\"muted\" style=\"margin:6px 0 12px\"><em>Le risque de prise de poids diminue avec : <span class=\"kw-ci\">allaitement</span> reçu dans l'enfance, activité physique, alimentation riche en fibres et de type méditerranéen.</em></p>\n      <p><strong>Cancers</strong></p>\n      <ul>\n        <li><span class=\"kw-chiffre\">&gt; 70 000 cancers/an</span> (≈ <span class=\"kw-chiffre\">20 %</span>) attribuables à des FDR nutritionnels, essentiellement <span class=\"kw-clinique\">sein</span> et <span class=\"kw-clinique\">colorectal (CCR)</span></li>\n        <li><span class=\"kw-alerte\">FDR</span> : alcool, viande rouge, charcuterie (CCR), surpoids/<span class=\"kw-etio\">obésité</span>, produits conservés dans le sel (cancer de l'estomac)</li>\n        <li><span class=\"kw-def\">Facteurs protecteurs</span> : AP régulière (CCR, sein, endomètre), fibres et céréales complètes, produits laitiers (CCR), légumes & fruits (VADS), café (foie, endomètre), <span class=\"kw-ci\">allaitement</span> (sein)</li>\n      </ul>\n      <p><strong>Autres pathologies chroniques</strong></p>\n      <ul>\n        <li>Rôle des facteurs nutritionnels dans l'<span class=\"kw-clinique\">inflammation</span> (ex : polyarthrite rhumatoïde)</li>\n        <li>Vitamines, minéraux antioxydants et AG polyinsaturés : ↓ du déclin cognitif et de la maladie d'Alzheimer (?)</li>\n        <li>Implication possible dans le déclenchement de la <span class=\"kw-clinique\">migraine</span></li>\n      </ul>","frequence":1},{"id":"248-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les effets de l'inactivité physique et de la sédentarité sur la santé","contenu":"<p>L'inactivité physique et la <span class=\"kw-etio\">sédentarité</span> sont des <strong><span class=\"kw-def\">facteurs de risque</span> indépendants</strong>, dont les effets délétères s'ajoutent à ceux de l'alimentation.</p>\n      <div class=\"callout callout-danger\"><strong>Conséquences de la <span class=\"kw-etio\">sédentarité</span> :</strong>\n        <ul>\n          <li>↑ <span class=\"kw-clinique\">Prévalence du surpoids et de l'obésité</span></li>\n          <li>↑ <span class=\"kw-alerte\">Mortalité</span></li>\n          <li>↑ Risque de <span class=\"kw-clinique\">diabète de type 2</span> et de <span class=\"kw-clinique\">maladies cardiovasculaires</span></li>\n          <li>Risque de <span class=\"kw-clinique\">déminéralisation osseuse</span> chez le sujet âgé</li>\n          <li><span class=\"kw-clinique\">Fonte musculaire</span> et risque de <span class=\"kw-alerte\">dénutrition</span> (notamment lors de l'alitement)</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-info\"><strong>Fractionner la <span class=\"kw-etio\">sédentarité</span> +++.</strong> Au-delà de la quantité totale d'AP, c'est le <strong>fractionnement de la durée de sédentarité</strong> qui est protecteur : interrompre régulièrement les périodes assises a un bénéfice propre, indépendant du fait de pratiquer par ailleurs une AP suffisante.</div>","frequence":0},{"id":"248-8","rang":"B","rubrique":"Étiologies","titre":"Connaître les différents freins aux changements de comportements","contenu":"<p>Les comportements alimentaires sont le <strong>reflet d'habitudes de longue date</strong> (histoire personnelle, familiale et culturelle). Tout changement doit être <span class=\"kw-def\">graduel</span> et respectueux des valeurs de l'individu pour être maintenu dans la durée.</p>\n      <p><strong>Freins environnementaux</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Environnement bâti</span> (peu propice à l'AP : absence d'espaces, transports…)</li>\n        <li><span class=\"kw-clinique\">Environnement alimentaire</span> : marketing alimentaire (promotion, placement et publicité pour des aliments de moins bonne qualité nutritionnelle), <strong>prix élevé</strong> des produits de bonne qualité</li>\n      </ul>\n      <p><strong>Freins individuels — causes d'absence de motivation</strong></p>\n      <ul>\n        <li>Absence de <span class=\"kw-clinique\">conscience des enjeux</span></li>\n        <li><span class=\"kw-clinique\">Déni</span> des conséquences</li>\n        <li>Appréhension des <span class=\"kw-clinique\">contraintes / frustrations</span></li>\n        <li>Faible <span class=\"kw-alerte\">sentiment d'auto-efficacité</span> (++ chez les populations défavorisées : faible estime de soi, difficulté à se projeter)</li>\n        <li>Absence d'<span class=\"kw-clinique\">autodétermination</span></li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Évaluer avant d'agir.</strong> Avant toute intervention, il faut <strong>évaluer la motivation et les freins éventuels</strong> propres au patient.</div>","frequence":0},{"id":"248-9","rang":"B","rubrique":"Étiologies","titre":"Connaître les repères de consommation des différentes catégories d'aliments bénéfiques pour la santé","contenu":"<div class=\"callout callout-info\"><strong>PNNS.</strong> Le respect des repères du <span class=\"kw-def\">Programme National Nutrition Santé</span> (Haut Conseil de la santé publique) est associé à une <span class=\"kw-chiffre\">↓ de la mortalité de 30 %</span>.</div>\n      <p><strong>Répartition des macronutriments</strong> (en part des apports énergétiques)</p>\n      <table >\n        <thead><tr><th>Macronutriment</th><th>Apports recommandés</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Glucides</span></td><td><span class=\"kw-chiffre\">50-55 %</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Lipides</span></td><td><span class=\"kw-chiffre\">30-40 %</span> (acides gras saturés <span class=\"kw-chiffre\">&lt; 10 %</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Protéines</span></td><td><span class=\"kw-chiffre\">10-20 %</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Fibres</span></td><td><span class=\"kw-chiffre\">30-45 g/jour</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Sel</span></td><td><span class=\"kw-chiffre\">&lt; 5-6 g/jour</span> — privilégier le <strong>sel iodé</strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>À privilégier / augmenter</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fruits et légumes</span> : <span class=\"kw-chiffre\">5/jour</span> (<span class=\"kw-chiffre\">80-100 g</span>/portion) — antioxydants & fibres ; <strong>pas plus d'un verre de jus de fruits/jour</strong> (compte comme une portion)</li>\n        <li><span class=\"kw-clinique\">Produits céréaliers complets</span> et peu raffinés : <strong>tous les jours</strong></li>\n        <li><span class=\"kw-clinique\">Légumineuses</span> : au moins <span class=\"kw-chiffre\">2×/semaine</span> (fibres et protéines végétales)</li>\n        <li><span class=\"kw-clinique\">Produits laitiers</span> : <span class=\"kw-chiffre\">2/jour</span> (<span class=\"kw-chiffre\">150 mL</span> de lait,<span class=\"kw-chiffre\"> 125 g</span> de yaourt,<span class=\"kw-chiffre\"> 30 g</span> de fromage)</li>\n        <li><span class=\"kw-clinique\">Poissons</span> : <span class=\"kw-chiffre\">2×/semaine</span>, dont un <strong>poisson gras</strong> (sardine, maquereau, hareng, saumon)</li>\n        <li><span class=\"kw-clinique\">Fruits à coque</span> : <strong>1 poignée/jour</strong> (attention aux allergies)</li>\n        <li><span class=\"kw-clinique\">Eau</span> : <strong>à volonté</strong>, pendant et entre les repas</li>\n      </ul>\n      <p><strong>À limiter</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Viande rouge</span> : <span class=\"kw-chiffre\">500 g/semaine max</span></li>\n        <li><span class=\"kw-clinique\">Charcuterie</span> : <span class=\"kw-chiffre\">150 g/semaine max</span> (jambon blanc ++)</li>\n        <li><span class=\"kw-clinique\">Matières grasses</span> : privilégier les végétales (colza, noix, olive) sans augmenter la quantité habituelle</li>\n        <li><span class=\"kw-clinique\">Produits sucrés</span> (y compris jus de fruits) et <span class=\"kw-clinique\">sel</span></li>\n        <li><span class=\"kw-alerte\">Alcool</span> : pas plus de <span class=\"kw-chiffre\">10 verres/semaine</span> et <span class=\"kw-chiffre\">2 verres/jour</span>, avec des jours sans consommation ; <strong>supprimé pendant la <span class=\"kw-ci\">grossesse</span></strong></li>\n      </ul>","frequence":0},{"id":"248-10","rang":"B","rubrique":"Prise en charge","titre":"Savoir conseiller les parents pour que leur enfant ait une alimentation adaptée","contenu":"<p>Les conseils sont adaptés à l'âge de l'enfant et visent à installer durablement de bonnes habitudes.</p>\n      <table >\n        <thead><tr><th>Âge</th><th>Conseils aux parents</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>0 à 36 mois</strong></span></td>\n            <td>\n              Alimentation <strong>lactée exclusive</strong> (++ <span class=\"kw-ci\">allaitement</span> maternel, sinon préparations pour nourrissons) ;\n              <strong>diversification vers <span class=\"kw-chiffre\">4-6 mois</span></strong> (privilégier les préparations maison) ;\n              <span class=\"kw-alerte\">pas de boissons végétales avant l'âge de 1 an</span> ;\n              respect des rythmes de sommeil ; <strong>pas d'exposition aux écrans avant <span class=\"kw-chiffre\">3 ans</span></strong>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>3 à 17 ans</strong></span></td>\n            <td>\n              <strong>Adapter la taille des portions</strong> (éviter un apport calorique excessif : env. la moitié des portions adultes chez les plus petits, portions adultes vers <span class=\"kw-chiffre\">11-12 ans</span>) ;\n              produits laitiers <span class=\"kw-chiffre\">× 3/jour</span> ;\n              éviter café, thé, sodas et boissons caféinées, édulcorants et boissons édulcorées ;\n              limiter les produits à base de soja et le chocolat ;\n              <strong><span class=\"kw-def\">surveillance</span> de la courbe de croissance et de l'IMC</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Éducation au comportement alimentaire</strong></p>\n      <ul>\n        <li>Éviter la <span class=\"kw-clinique\">néophobie alimentaire</span> : diversifier l'alimentation <strong>avant <span class=\"kw-chiffre\">2 ans</span></strong>, sans forcer</li>\n        <li>Se baser sur les <span class=\"kw-clinique\">signaux internes</span> : rassasiement, faim</li>\n        <li><span class=\"kw-alerte\">Éviter les restrictions alimentaires</span></li>\n        <li>Ambiance sereine au repas, temps de mastication suffisant</li>\n      </ul>","frequence":0},{"id":"248-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les recommandations d'activité physique chez l'enfant et l'adulte","contenu":"<p>Les recommandations associent toujours un <strong>volume d'AP</strong> à une <strong><span class=\"kw-ttt\">réduction</span> de la <span class=\"kw-etio\">sédentarité</span></strong>.</p>\n      <table >\n        <thead><tr><th>Population</th><th>Activité physique</th><th>Sédentarité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Adultes</strong></span></td>\n            <td>\n              <span class=\"kw-chiffre\">30 min</span> d'AP modérée à élevée <span class=\"kw-chiffre\">≥ 5×/sem</span> (éviter <span class=\"kw-chiffre\">2 jours</span> consécutifs sans AP) ;\n              inclure de courtes périodes d'intensité élevée ;\n              <strong>renforcement musculaire 1-2×/sem</strong> (8-10 exercices, 2-3 séries de 10-15 répétitions) ;\n              assouplissement 2-3×/sem\n            </td>\n            <td>Interrompre la <span class=\"kw-etio\">sédentarité</span> au moins toutes les <span class=\"kw-chiffre\">90-120 min</span> par une marche de <span class=\"kw-chiffre\">3-5 min</span> + mobilisation musculaire</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Enfants &lt; 5 ans</strong></span></td>\n            <td><span class=\"kw-chiffre\">3 h/jour</span> d'AP (soit ≈<span class=\"kw-chiffre\"> 15 min</span>/h) ; favoriser le jeu et le plaisir, diversifier les activités</td>\n            <td>Ne pas dépasser <span class=\"kw-chiffre\">60 min</span> en continu ; écran <strong>totalement <span class=\"kw-ci\">proscrit</span> avant <span class=\"kw-chiffre\">2 ans</span></strong>, <span class=\"kw-chiffre\">&lt; 1 h/jour</span> avant <span class=\"kw-chiffre\">5 ans</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Enfants 6-17 ans</strong></span></td>\n            <td>Au moins <span class=\"kw-chiffre\">60 min/jour</span> d'AP modérée à élevée ; tous les <span class=\"kw-chiffre\">2 jours</span>, <span class=\"kw-chiffre\">≥ 20 min</span> d'activité intense + renforcement musculaire</td>\n            <td>Ne pas dépasser <span class=\"kw-chiffre\">120 min</span> en continu ; temps d'écran de loisirs <span class=\"kw-chiffre\">&lt; 2 h/jour</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Personnes âgées &gt; 65 ans</strong></span></td>\n            <td>\n              <span class=\"kw-chiffre\">30 min/jour</span> d'AP modérée (faible essoufflement) ;\n              renforcement musculaire <span class=\"kw-chiffre\">≥ 2 jours</span>/sem non consécutifs ;\n              assouplissement 2-3×/sem ;\n              <strong>exercices d'équilibre <span class=\"kw-chiffre\">≥ 2 jours</span>/sem</strong> non consécutifs\n            </td>\n            <td>Interrompre la <span class=\"kw-etio\">sédentarité</span> au moins toutes les <span class=\"kw-chiffre\">90-120 min</span> par une activité de <span class=\"kw-chiffre\">5 min</span> avec mobilisation musculaire</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"248-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes d'une alimentation équilibrée","contenu":"<div class=\"callout callout-info\"><strong>Cadre.</strong> Le médecin a un <strong>rôle central dans la <span class=\"kw-def\">prévention primaire</span></strong>. L'<span class=\"kw-def\">objectif prioritaire</span> d'une alimentation équilibrée est la <span class=\"kw-alerte\">stabilisation du poids</span> et la <span class=\"kw-ttt\">réduction</span> du risque de maladies liées à la nutrition.</div>\n      <p><strong>Principes comportementaux</strong></p>\n      <ul>\n        <li>Éviter le <span class=\"kw-clinique\">grignotage</span></li>\n        <li><strong>Prendre le temps</strong> de manger et de profiter des repas</li>\n        <li>Éviter les consommations et les <span class=\"kw-clinique\">portions excessives</span></li>\n        <li>Privilégier le <span class=\"kw-def\">« fait maison »</span></li>\n        <li>Réduire la consommation des aliments de <span class=\"kw-alerte\">Nutri-Score D ou E</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Adapter selon le <span class=\"kw-def\">terrain</span>.</strong> Chez la <span class=\"kw-clinique\">personne âgée</span> : besoins énergétiques et rendement alimentaire/synthèse protéique diminués → <strong>maintenir les quantités habituelles</strong> et tripler les portions de produits laitiers (× 3).</div>\n      <p class=\"obj-renvois\"><em>📎 Les repères chiffrés par catégorie d'aliments (PNNS) sont détaillés dans l'objectif « repères de consommation ».</em></p>","frequence":1},{"id":"248-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les moyens de la prévention primaire par la nutrition","contenu":"<div class=\"callout callout-info\"><strong>Prévention (OMS).</strong> Ensemble des mesures visant <span class=\"kw-ci\">à éviter</span> ou réduire le nombre et la gravité des maladies, accidents et handicaps. La <span class=\"kw-def\">prévention primaire</span> agit <strong>avant l'apparition de la maladie</strong> : elle vise à diminuer l'<span class=\"kw-def\">incidence</span> dans une population en ciblant les conduites individuelles à risque et les risques environnementaux ou sociétaux (ex : vaccination).</div>\n      <p><strong>Levier individuel — le travail motivationnel +++</strong></p>\n      <ul>\n        <li>Expliquer l'<span class=\"kw-clinique\">enjeu de santé</span> et l'impact négatif, <strong>sans jugement ni stigmatisation</strong></li>\n        <li>Identifier les changements nécessaires et leurs conséquences</li>\n        <li>Préserver le <span class=\"kw-clinique\">plaisir de manger</span> et respecter le <strong>libre arbitre</strong> du patient</li>\n        <li>Aide et accompagnement dans le changement ; implication de l'<span class=\"kw-clinique\">entourage</span></li>\n        <li>Prise en compte de la situation alimentaire (histoire, culture, contexte psychosocial)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Motivation intrinsèque +++.</strong> La <span class=\"kw-def\">motivation intrinsèque</span> (personnelle) est le <strong>préalable</strong> à toute démarche ; la <span class=\"kw-clinique\">motivation extrinsèque</span> est <span class=\"kw-alerte\">insuffisante à elle seule</span>.</div>\n      <p><strong>Approche relationnelle</strong> : empathie, <span class=\"kw-clinique\">écoute active bienveillante</span>, questions ouvertes et technique de reformulation.</p>\n      <p><strong>Leviers collectifs / environnementaux</strong> : PNNS, Nutri-<span class=\"kw-def\">Score</span>, action sur le marketing et l'environnement alimentaire, accessibilité (prix) des produits de qualité.</p>","frequence":0}],"astuces":[{"type":"warn","titre":"Inactivité ≠ sédentarité (piège classique)","contenu":"<p><span class=\"kw-def\">Inactivité physique</span> = <strong>défaut d'AP</strong> (&lt; 30 min/j d'AP modérée × 5/sem adulte ; &lt; 60 min/j enfant). <span class=\"kw-def\">Sédentarité</span> = <strong>excès de temps assis/couché éveillé</strong> (dépense &lt; 1,6 MET). <strong>On peut être actif ET sédentaire</strong> (sport 1 h/j + 10 h de bureau) — ce sont <strong>2 cibles de prévention distinctes</strong>. Le <strong>fractionnement</strong> de la sédentarité a un bénéfice propre, indépendant du volume d'AP.</p>"},{"type":"tip","titre":"Repères PNNS à mémoriser","contenu":"<p><strong>Fruits/légumes <span class=\"kw-chiffre\">5/j</span></strong> · légumineuses <span class=\"kw-chiffre\">2×/sem</span> · poisson <span class=\"kw-chiffre\">2×/sem</span> dont 1 gras · produits laitiers <span class=\"kw-chiffre\">2/j</span> (<span class=\"kw-chiffre\">3/j</span> enfant, <span class=\"kw-chiffre\">3-4/j</span> personne âgée) · fruits à coque 1 poignée/j.<br><strong>Plafonds</strong> : viande rouge <span class=\"kw-chiffre\">≤ 500 g/sem</span>, charcuterie <span class=\"kw-chiffre\">≤ 150 g/sem</span>, sel <span class=\"kw-chiffre\">&lt; 5-6 g/j</span> (iodé), AGS <span class=\"kw-chiffre\">&lt; 10 %</span>, alcool <span class=\"kw-chiffre\">≤ 10 verres/sem</span> et <span class=\"kw-chiffre\">≤ 2/j</span>.</p>"},{"type":"warn","titre":"Recommandations AP par âge","contenu":"<p><strong>Adulte</strong> : <span class=\"kw-chiffre\">30 min</span> AP modérée <span class=\"kw-chiffre\">≥ 5×/sem</span> + renforcement musculaire <span class=\"kw-chiffre\">1-2×/sem</span>. <strong>Enfant 6-17 ans</strong> : <span class=\"kw-chiffre\">≥ 60 min/j</span> AP modérée-élevée. <strong>Enfant &lt; 5 ans</strong> : <span class=\"kw-chiffre\">3 h/j</span> ; écrans <span class=\"kw-ci\">proscrits &lt; 2 ans</span>, <span class=\"kw-chiffre\">&lt; 1 h/j</span> avant 5 ans. <strong>&gt; 65 ans</strong> : <span class=\"kw-chiffre\">30 min/j</span> + <strong>équilibre <span class=\"kw-chiffre\">≥ 2 j/sem</span></strong>. Interrompre la sédentarité toutes les <span class=\"kw-chiffre\">90-120 min</span>.</p>"},{"type":"tip","titre":"Motivation intrinsèque = préalable","contenu":"<p>La <span class=\"kw-def\">motivation intrinsèque</span> (personnelle, autodéterminée) est le <strong>préalable à tout changement durable</strong> ; la motivation extrinsèque est <span class=\"kw-alerte\">insuffisante à elle seule</span>. Repérer les freins (déni, faible auto-efficacité, contraintes) et travailler par <strong>entretien motivationnel</strong> (empathie, écoute active, sans jugement). La menace de complications est <span class=\"kw-alerte\">ni éthique ni efficace</span>.</p>"}],"strategie":{"urgence":"<p><strong>Avis médical préalable :</strong> recommandé avant toute <span class=\"kw-ttt\">activité physique d'intensité ≥ modérée</span>.<br><strong><span class=\"kw-alerte\">Décompensation</span> cardiaque :</strong> chez l'insuffisant cardiaque, <span class=\"kw-clinique\">consulter rapidement si prise de poids de 2-3 kg en 2-3 jours</span>, a fortiori si elle est <span class=\"kw-alerte\">soudaine</span>.<br><strong><span class=\"kw-alerte\">Mort subite</span> du sportif :</strong> <span class=\"kw-alerte\">premier danger</span> de la pratique — <span class=\"kw-def\">dépistage</span> par <span class=\"kw-imagerie\">ECG de repos</span> associé à l'examen clinique (détecte <span class=\"kw-chiffre\">60 à 90 %</span> des cardiopathies responsables, contre <span class=\"kw-chiffre\">5 %</span> pour la clinique seule).<br><strong>CI temporaires (différer l'AP) :</strong> <span class=\"kw-ci\">affection inflammatoire ou infectieuse évolutive</span>, <span class=\"kw-ci\">exacerbation respiratoire récente < 3 semaines</span>, <span class=\"kw-ci\">diabète non contrôlé avec acétonurie/acétonémie</span>.</p>","hospit":"<p><strong>Prescription diététique :</strong> <span class=\"kw-def\">acte médicolégal</span> engageant la responsabilité du médecin ; <span class=\"kw-ttt\">prescription écrite obligatoire chez le patient hospitalisé</span> lorsqu'un régime est nécessaire à la bonne gestion de sa/ses maladie(s).<br><strong>Contenu de la prescription :</strong> type d'alimentation, <span class=\"kw-ttt\">texture alimentaire</span>, nombre de collations, <span class=\"kw-ttt\">compléments nutritionnels oraux</span>, aide aux repas, <span class=\"kw-ttt\">mesures posturales de prévention des fausses routes</span>.<br><strong>Orientation vers l'AP adaptée :</strong> prescription sur <span class=\"kw-ttt\">ordonnance ou carnet de liaison</span> vers un <span class=\"kw-ttt\">enseignant en activité physique adaptée</span> (éducateur médicosportif) ; dispositif <span class=\"kw-ttt\">Prescri'mouv</span> promu par les ARS.<br><strong>Bilan médical préalable (HAS) :</strong> indiqué si <span class=\"kw-clinique\">autoquestionnaire Q-AAP positif</span>, personne <span class=\"kw-clinique\">inactive de plus de 45 ans</span>, <span class=\"kw-clinique\">AP d'intensité très élevée</span>, ou <span class=\"kw-alerte\">suspicion de maladie cardiaque, pulmonaire, métabolique ou rénale</span>.</p>","redflags":"<ul><li><strong><span class=\"kw-ci\">CI absolues</span> à l'AP ≥ modérée :</strong> <span class=\"kw-ci\">angor instable</span>, <span class=\"kw-ci\">insuffisance cardiaque décompensée</span>, <span class=\"kw-ci\">troubles du rythme ventriculaires complexes</span>, <span class=\"kw-ci\">HTA sévère non contrôlée</span>, <span class=\"kw-ci\">HTAP > 60 mmHg</span></li><li><span class=\"kw-ci\">Rétrécissement aortique serré et/ou symptomatique</span>, <span class=\"kw-ci\">myocardiopathie obstructive sévère</span>, <span class=\"kw-ci\">thrombus intracavitaire volumineux ou pédiculé</span>, <span class=\"kw-ci\">thrombophlébite récente</span>, <span class=\"kw-ci\">épanchement péricardique aigu</span>, <span class=\"kw-ci\">diabète avec mal perforant plantaire</span> (AP des membres inférieurs)</li><li><span class=\"kw-ci\">HTA non contrôlée</span> : l'<span class=\"kw-alerte\">activité physique d'intensité élevée est contre-indiquée</span></li><li><strong><span class=\"kw-alerte\">Mort subite</span> du sportif</strong> (1er danger) : avant <span class=\"kw-chiffre\">35 ans</span> évoquer <span class=\"kw-etio\">CMH</span>, <span class=\"kw-etio\">DAVD</span>, <span class=\"kw-etio\">myocardite</span>, <span class=\"kw-etio\">rupture aortique</span> ; après <span class=\"kw-chiffre\">35 ans</span> <span class=\"kw-etio\">coronaropathie athéromateuse</span></li><li><strong>État de surentraînement :</strong> <span class=\"kw-clinique\">chute progressive des performances</span>, <span class=\"kw-clinique\">troubles du sommeil et de l'appétit</span>, <span class=\"kw-clinique\">élévation de la FC et de la PA de repos</span> (diagnostic d'élimination)</li><li><strong>Triade de l'athlète féminine :</strong> <span class=\"kw-etio\">désordres alimentaires (TCA)</span> + <span class=\"kw-clinique\">aménorrhée hypothalamique fonctionnelle</span> + <span class=\"kw-alerte\">ostéoporose</span> (fractures de fatigue)</li><li><strong>Comportement alimentaire à risque :</strong> <span class=\"kw-etio\">accès boulimique (binge eating)</span> = envie irrépressible de manger avec <span class=\"kw-alerte\">perte de contrôle</span> de l'acte</li></ul>","principes":"<p>La <span class=\"kw-def\">prévention primaire</span> repose sur une <span class=\"kw-ttt\">alimentation équilibrée</span> (repères PNNS), une <span class=\"kw-ttt\">activité physique régulière</span> et la <span class=\"kw-ttt\">lutte contre la sédentarité</span> ; l'<span class=\"kw-def\">objectif prioritaire</span> est la <span class=\"kw-alerte\">stabilisation du poids</span> et la <span class=\"kw-ttt\">réduction</span> du risque de maladies liées à la nutrition. Toute modification est précédée d'une <span class=\"kw-def\">évaluation du comportement alimentaire</span> et des freins au changement.</p><p><strong>Repères nutritionnels (PNNS / HCSP)</strong></p><p>Répartition des apports : <span class=\"kw-chiffre\">50-55 %</span> glucides, <span class=\"kw-chiffre\">30-40 %</span> lipides, <span class=\"kw-chiffre\">10-20 %</span> protéines</p><ul><li><span class=\"kw-ttt\">Fruits et légumes</span> : <span class=\"kw-chiffre\">5 par jour</span> ; <span class=\"kw-ttt\">légumineuses</span> <span class=\"kw-chiffre\">2x/semaine</span> ; <span class=\"kw-ttt\">poisson</span> <span class=\"kw-chiffre\">2x/semaine</span> dont <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>ras ; <span class=\"kw-ttt\">fibres</span> <span class=\"kw-chiffre\">30-45 g/j</span></li><li>Limiter : <span class=\"kw-ttt\">viande rouge</span> ≤ <span class=\"kw-chiffre\">500 g/semaine</span>, <span class=\"kw-ttt\">charcuterie</span> ≤ <span class=\"kw-chiffre\">150 g/semaine</span>, <span class=\"kw-ttt\">acides gras saturés</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">10 %</span></span>, produits sucrés</li><li><span class=\"kw-ttt\">Sel</span> < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">5-6 g</span>/j</span> (privilégier le sel iodé) ; <span class=\"kw-ttt\">alcool</span> ≤ <span class=\"kw-chiffre\">10 verres/semaine</span> et ≤ <span class=\"kw-chiffre\">2/jour</span>, avec jours sans consommation, supprimé pendant la <span class=\"kw-ci\">grossesse</span></li><li><span class=\"kw-ttt\">Eau</span> = seule boisson recommandée, à volonté</li></ul><p><strong>Activité physique (règle des 3R)</strong></p><p><span class=\"kw-clinique\">Repos strict non souhaitable</span> dans l'<span class=\"kw-ci\">insuffisance cardiaque</span> (déconditionnement) ; renforcement après programme de réadaptation spécialisée pour cardiopathie/BPCO</p><ul><li><span class=\"kw-def\">3R</span> : raisonnée, régulière, raisonnable</li><li><span class=\"kw-ttt\">Endurance</span> : intensité modérée (≥ <span class=\"kw-chiffre\">3 MET</span>) <span class=\"kw-chiffre\">30 min/j, 5x/semaine</span> (≥ <span class=\"kw-chiffre\">2h30/semaine</span>), ou intensité élevée (≥ <span class=\"kw-chiffre\">6 MET</span>) <span class=\"kw-chiffre\">1h15/semaine</span></li><li><span class=\"kw-ttt\">Renforcement musculaire</span> ≥ <span class=\"kw-chiffre\">2-3x/semaine</span> ± exercices d'équilibre chez la personne âgée à risque de chutes</li><li>Le <span class=\"kw-alerte\">gain de santé maximal</span> est obtenu au passage d'<span class=\"kw-clinique\">inactif à modérément actif</span> (relation curvilinéaire) ; <span class=\"kw-ttt\">réduction</span> de la <span class=\"kw-alerte\">mortalité cardiovasculaire de 30 %</span>, dose-dépendante</li></ul><p><strong>Évaluation préalable & conseil</strong></p><p>La <span class=\"kw-def\">motivation intrinsèque</span> est le préalable à toute démarche ; la motivation extrinsèque est <span class=\"kw-alerte\">insuffisante à elle seule</span></p><ul><li><span class=\"kw-def\">Évaluer le comportement alimentaire</span> avant toute modification : <span class=\"kw-etio\">grignotage</span>, <span class=\"kw-etio\">restriction cognitive</span>, <span class=\"kw-etio\">tachyphagie</span>, <span class=\"kw-etio\">compulsions (craving)</span>, <span class=\"kw-etio\">accès boulimique</span></li><li>Respecter les <span class=\"kw-clinique\">signaux internes de faim et de rassasiement</span> ; <span class=\"kw-ttt\">éviter les restrictions alimentaires</span> (sources de frustration et de compensations)</li><li><span class=\"kw-def\">Conseil nutritionnel = démarche d'éducation thérapeutique</span> : respecter le rythme et le <span class=\"kw-clinique\">choix du patient</span>, identifier les <span class=\"kw-clinique\">freins au changement</span></li></ul><p><strong>Adaptations selon la pathologie</strong></p><p>Population à risque (obèse, <span class=\"kw-etio\">HTA</span> contrôlée, diabétique) : ajout du <span class=\"kw-ttt\">renforcement musculaire ≥ 3x/semaine</span></p><ul><li><span class=\"kw-etio\">Obésité</span> : viser d'abord la <span class=\"kw-ttt\">stabilisation du poids</span> ; une perte de <span class=\"kw-chiffre\">5-10 %</span> apporte déjà un bénéfice significatif</li><li><span class=\"kw-etio\">HTA</span> : <span class=\"kw-ttt\">régime hyposodé < 5-6 g/j</span>, perte de poids (objectif IMC <span class=\"kw-chiffre\">20-25</span>), arrêt du tabac et réduction de l'alcool</li><li><span class=\"kw-etio\">Insuffisance cardiaque</span> : <span class=\"kw-ttt\">régime hyposodé 5-6 g/j systématique</span>, AP régulière non essoufflante, arrêt impératif du tabac</li><li><span class=\"kw-etio\">Diabète de type 2</span> : <span class=\"kw-ttt\">apport régulier en glucides à chaque repas</span> pour éviter les variations glycémiques sous hypoglycémiants</li></ul>","suivi":"<p><strong><span class=\"kw-etio\">HTA</span> :</strong> efficacité du <span class=\"kw-ttt\">régime hyposodé</span> contrôlable par la <span class=\"kw-bio\">natriurèse</span> ; seulement <span class=\"kw-chiffre\">45 %</span> des patients sont répondeurs à la restriction sodée.<br><strong><span class=\"kw-ci\">Insuffisance cardiaque</span> :</strong> <span class=\"kw-clinique\">surveillance du poids et des symptômes</span> ; une <span class=\"kw-clinique\">perte de poids progressive sans œdème</span> signe une <span class=\"kw-alerte\">dénutrition</span> (mauvais <span class=\"kw-def\">pronostic</span>).<br><strong>Activité physique :</strong> <span class=\"kw-imagerie\">podomètre ou objets connectés</span> pour suivre la progression et renforcer la motivation ; le <span class=\"kw-def\">suivi</span> est indispensable car le maintien du comportement actif est difficile.<br><strong>Relais :</strong> partenariat avec clubs, fédérations et <span class=\"kw-ttt\">réseaux sport-santé</span> ; adapter les objectifs dans la durée.<br><strong><span class=\"kw-imagerie\">Épreuve d'effort</span> :</strong> si réalisée, peut être <span class=\"kw-imagerie\">répétée tous les 5 ans</span> (pas de consensus formel).</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Contre-indication absolue à une AP d'intensité ≥ modérée ? — Avant toute prescription d'activité physique","detail":"<h4>CAT — Prescrire une activité physique en <span class=\"kw-def\">prévention primaire</span> — Évaluation préalable, <span class=\"kw-ci\">contre-indications</span> et orientation</h4>","branches":[{"to":"t-ci-abs","label":"Oui — CI absolue présente","color":"red"},{"to":"q-bilan","label":"Non","color":"blue"}]},{"id":"t-ci-abs","kind":"terminal","label":"CI absolue → AP ≥ modérée contre-indiquée","color":"red","detail":"<h4>CI cardiovasculaires</h4><ul><li><span class=\"kw-ci\">Angor instable</span>, <span class=\"kw-ci\">insuffisance cardiaque décompensée</span>, <span class=\"kw-ci\">troubles du rythme ventriculaires complexes</span></li><li><span class=\"kw-ci\">HTA sévère non contrôlée</span>, <span class=\"kw-ci\">HTAP > 60 mmHg</span>, <span class=\"kw-ci\">RAo serré et/ou symptomatique</span>, <span class=\"kw-ci\">myocardiopathie obstructive sévère</span></li><li><span class=\"kw-ci\">Thrombus intracavitaire</span>, <span class=\"kw-ci\">thrombophlébite récente</span>, <span class=\"kw-ci\">épanchement péricardique aigu</span></li></ul><h4>Autres <span class=\"kw-ci\">CI absolues</span> / temporaires</h4><ul><li><span class=\"kw-ci\">Diabète avec mal perforant plantaire</span> (AP sollicitant les membres inférieurs)</li><li>Temporaires : <span class=\"kw-ci\">affection inflammatoire/infectieuse évolutive</span>, <span class=\"kw-ci\">exacerbation respiratoire < 3 semaines</span>, <span class=\"kw-ci\">diabète non contrôlé avec acétonurie</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Traiter et stabiliser la pathologie</span> avant d'envisager une AP ≥ modérée</li></ul>"},{"id":"q-bilan","kind":"decision","label":"Indication HAS d'un bilan médical avant l'AP ? — Q-AAP+, inactif > 45 ans, AP très élevée, suspicion de maladie cardiaque/pulmonaire/métabolique/rénale","branches":[{"to":"t-pas-bilan","label":"Aucune indication HAS","color":"green"},{"to":"q-intensite","label":"Indication de bilan médical","color":"amber"}]},{"id":"t-pas-bilan","kind":"terminal","label":"AP peut débuter — aucun examen requis","color":"green","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-clinique\">Sujet jeune asymptomatique</span>, <span class=\"kw-clinique\">RCV faible</span>, AP d'intensité légère à modérée</li><li><span class=\"kw-imagerie\">Aucun examen paraclinique indispensable</span> (<span class=\"kw-imagerie\">épreuve d'effort</span> non recommandée ici)</li></ul><h4>Conseils (règle des 3R)</h4><ul><li><span class=\"kw-ttt\">Endurance</span> modérée ≥ <span class=\"kw-chiffre\">30 min/j, 5x/semaine</span> (≥ <span class=\"kw-chiffre\">2h30/semaine</span>) + <span class=\"kw-ttt\">renforcement musculaire</span> ≥ <span class=\"kw-chiffre\">2-3x/semaine</span></li><li>Débuter <span class=\"kw-clinique\">progressivement</span> et <span class=\"kw-ttt\">lutter contre la sédentarité</span> (rester moins longtemps assis)</li></ul>"},{"id":"q-intensite","kind":"decision","label":"AP d'intensité élevée à haut risque ? — RCV élevé/très élevé, ATCD familial de <span class=\"kw-alerte\">mort subite</span> < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>50</span> ans</span>, patient symptomatique","branches":[{"to":"t-ee","label":"Intensité élevée + haut risque","color":"red"},{"to":"t-ap-adaptee","label":"Sinon — risque maîtrisé","color":"green"}]},{"id":"t-ee","kind":"terminal","label":"Épreuve d'effort avant l'AP","color":"red","detail":"<h4>Indications</h4><ul><li><span class=\"kw-clinique\">Patient symptomatique</span></li><li>AP d'<span class=\"kw-clinique\">intensité élevée</span> si <span class=\"kw-alerte\">RCV élevé ou très élevé</span>, ou <span class=\"kw-etio\">ATCD familial de cardiopathie héréditaire/congénitale ou de mort subite</span> chez un parent du 1er degré < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">50 ans</span></span></li></ul><h4>Examen</h4><ul><li><span class=\"kw-imagerie\">EE maximale + ECG continu</span> ± analyse des gaz expirés ; objectif : dépister une <span class=\"kw-etio\">coronaropathie</span> ou un <span class=\"kw-etio\">trouble du rythme à l'effort</span></li><li>Avis <span class=\"kw-ttt\">cardiologue</span> ; chez le sujet ≥ <span class=\"kw-chiffre\">35 ans</span>, l'EE remplace l'<span class=\"kw-imagerie\">ECG de repos</span></li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li><span class=\"kw-imagerie\">EE répétée tous les 5 ans</span> (pas de consensus formel)</li></ul>"},{"id":"t-ap-adaptee","kind":"terminal","label":"AP adaptée encadrée","color":"green","detail":"<h4>Orientation</h4><ul><li>Prescription sur <span class=\"kw-ttt\">ordonnance ou carnet de liaison</span> vers un <span class=\"kw-ttt\">enseignant en activité physique adaptée</span> (éducateur médicosportif)</li><li>Dispositif <span class=\"kw-ttt\">Prescri'mouv</span> (ARS)</li></ul><h4>Programme</h4><ul><li><span class=\"kw-ttt\">Endurance + renforcement musculaire</span> (après programme de réadaptation spécialisée si cardiopathie/BPCO)</li><li>Adapter à la pathologie chronique et aux <span class=\"kw-def\">comorbidités</span> (évaluation cardiologique préalable si besoin)</li></ul><h4>Population à risque</h4><ul><li>Obèse / <span class=\"kw-etio\">HTA</span> contrôlée / DT2 : ajout du <span class=\"kw-ttt\">renforcement musculaire ≥ 3x/semaine</span></li><li><span class=\"kw-ci\">HTA non contrôlée</span> → <span class=\"kw-alerte\">AP d'intensité élevée contre-indiquée</span></li></ul>"}]},"cards":[{"i":"2a9c3a911a5f","n":248,"o":"248-1","u":"Définition","t":"Connaître la définition de l'activité physique, de l'inactivité physique, de la sédentarité et de la condition physique","q":"Qu'est-ce que la sédentarité et par quel indicateur est-elle caractérisée ?","a":"<p>La <strong>sédentarité</strong> est un comportement caractérisé par une position <strong>assise ou couchée dominante à l'éveil</strong>, associée à une <strong>faible dépense énergétique</strong>, généralement inférieure à <strong>1,6 MET</strong> (Metabolic Equivalent of Task).</p>"},{"i":"391ef9e8fdbe","n":248,"o":"248-1","u":"Définition","t":"Connaître la définition de l'activité physique, de l'inactivité physique, de la sédentarité et de la condition physique","q":"Quelle est la différence fondamentale entre inactivité physique et sédentarité ?","a":"<p>L'<strong>inactivité physique</strong> est un défaut d'activité physique, c'est-à-dire l'absence d'atteinte des seuils recommandés d'activité. La <strong>sédentarité</strong> est un excès de temps passé assis ou couché. Il est possible d'être à la fois physiquement actif (en atteignant les seuils recommandés) et sédentaire (en passant beaucoup de temps assis par ailleurs), ce sont donc <strong>deux cibles de prévention distinctes</strong>.</p>"},{"i":"a0f39d5de586","n":248,"o":"248-1","u":"Définition","t":"Connaître la définition de l'activité physique, de l'inactivité physique, de la sédentarité et de la condition physique","q":"Quelle est la définition de l'activité physique (AP) en médecine préventive ?","a":"<p>L'<strong>activité physique</strong> est définie comme tout mouvement produit par les <strong>muscles squelettiques</strong> entraînant une <strong>augmentation de la dépense énergétique</strong> au-dessus de la valeur de repos.</p>"},{"i":"aecfe06691f7","n":248,"o":"248-1","u":"Définition","t":"Connaître la définition de l'activité physique, de l'inactivité physique, de la sédentarité et de la condition physique","q":"Comment définit-on l'inactivité physique chez l'adulte et chez l'enfant ?","a":"<p>L'<strong>inactivité physique</strong> correspond à un niveau d'activité physique insuffisant :</p><ul><li>Chez l'<strong>adulte</strong> : moins de <strong>30 minutes par jour</strong> d'activité physique modérée ou intense, au minimum <strong>5 fois par semaine</strong>.</li><li>Chez l'<strong>enfant</strong> : moins de <strong>60 minutes par jour</strong> d'activité physique.</li></ul>"},{"i":"c862e77ff6a9","n":248,"o":"248-1","u":"Définition","t":"Connaître la définition de l'activité physique, de l'inactivité physique, de la sédentarité et de la condition physique","q":"Quelle est la définition de la condition physique ?","a":"<p>La <strong>condition physique</strong> est la capacité générale de l'organisme à réaliser les activités de la vie quotidienne sans fatigue excessive et à <strong>répondre favorablement à l'effort</strong>. Elle englobe l'<strong>endurance cardio-respiratoire</strong>, l'équilibre, la souplesse, la force, et la flexibilité musculaire.</p>"},{"i":"5121d8fb0054","n":248,"o":"248-12","u":"Prise en charge","t":"Connaître les grands principes d'une alimentation équilibrée","q":"Quelles sont les particularités des recommandations nutritionnelles pour la personne âgée dans le cadre d'une alimentation équilibrée ?","a":"<p>Chez la personne âgée, il convient de <strong>maintenir les quantités habituelles</strong> et de <strong>tripler les portions de produits laitiers (× 3)</strong>, en raison de besoins énergétiques et d'un rendement alimentaire/synthèse protéique diminués.</p>"},{"i":"dc4315b96052","n":248,"o":"248-12","u":"Prise en charge","t":"Connaître les grands principes d'une alimentation équilibrée","q":"Quels sont les principes comportementaux fondamentaux à conseiller pour une alimentation équilibrée en prévention primaire ?","a":"<ul><li>Éviter le <strong>grignotage</strong>.</li><li>Prendre le temps de manger et de profiter des repas.</li><li>Éviter les <strong>consommations et les portions excessives</strong>.</li><li>Privilégier le « <strong>fait maison</strong> ».</li><li>Réduire la consommation des aliments de <strong>Nutri-Score D ou E</strong>.</li></ul>"},{"i":"f366ce09a8a0","n":248,"o":"248-12","u":"Prise en charge","t":"Connaître les grands principes d'une alimentation équilibrée","q":"Quel est l'objectif prioritaire d'une alimentation équilibrée dans le cadre de la prévention primaire, selon l'EDN ?","a":"<p>L'objectif prioritaire est la <strong>stabilisation du poids</strong> et la <strong>réduction du risque de maladies liées à la nutrition</strong>.</p>"},{"i":"07267abe0d30","n":248,"o":"248-2","u":"Définition","t":"Connaître la définition définir et expliquer les différentes modalités d'activité physique","q":"Comment l'activité physique peut-elle être caractérisée ou déclinée selon le contexte de réalisation ?","a":"<p>L'activité physique se décline en plusieurs catégories selon le contexte de réalisation :</p><ul><li><strong>Activité physique liée aux déplacements</strong> (ex: marche, vélo).</li><li><strong>Activité physique liée à l'activité professionnelle et/ou scolaire</strong>.</li><li><strong>Activité physique de loisirs</strong> (ex: sport, jardinage).</li></ul>"},{"i":"ac99c7049203","n":248,"o":"248-2","u":"Définition","t":"Connaître la définition définir et expliquer les différentes modalités d'activité physique","q":"Comment mesure-t-on l'intensité de l'activité physique, et quelle est l'unité de référence utilisée ?","a":"<p>L'intensité de l'activité physique se mesure à l'aide du <strong>MET (Metabolic Equivalent of Task)</strong>. Le MET est défini comme le rapport de la dépense énergétique de l'activité sur le métabolisme de base, où <strong>1 MET</strong> représente le coût énergétique d'une personne au repos total. La valeur en MET augmente avec l'intensité de l'activité.</p>"},{"i":"c9aa41bd16f9","n":248,"o":"248-2","u":"Définition","t":"Connaître la définition définir et expliquer les différentes modalités d'activité physique","q":"Comment définit-on le temps de sédentarité ?","a":"<p>Le temps de sédentarité correspond au <strong>temps quotidien passé assis ou allongé sans bouger</strong>.</p>"},{"i":"f657eea02319","n":248,"o":"248-2","u":"Définition","t":"Connaître la définition définir et expliquer les différentes modalités d'activité physique","q":"Quels sont les quatre paramètres clés qui définissent une activité physique ?","a":"<p>Une activité physique est définie par quatre paramètres principaux :</p><ul><li>La <strong>durée</strong>.</li><li>L'<strong>intensité</strong>.</li><li>La <strong>fréquence</strong>.</li><li>Le <strong>type/contexte de réalisation</strong>.</li></ul>"},{"i":"300022ea596b","n":248,"o":"248-5","u":"Étiologies","t":"Connaître les principaux effets de l'activité physique et de la condition physique sur la santé en prévention primaire","q":"Quels sont les effets spécifiques de l'activité physique régulière chez l'enfant en prévention primaire ?","a":"<ul><li>Améliore la <strong>condition physique</strong>, la composition corporelle et la santé osseuse</li><li>Diminue les <strong>facteurs de risque cardiovasculaires</strong></li><li>Améliore la <strong>santé mentale</strong> : renforce la confiance, l'estime de soi, diminue l'anxiété, le stress et la dépression</li><li>Facteur favorable de <strong>réussite scolaire</strong></li></ul>"},{"i":"3186e6062975","n":248,"o":"248-5","u":"Étiologies","t":"Connaître les principaux effets de l'activité physique et de la condition physique sur la santé en prévention primaire","q":"Quelle est l'importance de l'activité physique en prévention primaire ?","a":"<p>L'activité physique est un <strong>déterminant majeur de santé</strong> en prévention primaire.</p>"},{"i":"4e5bf55e457e","n":248,"o":"248-5","u":"Étiologies","t":"Connaître les principaux effets de l'activité physique et de la condition physique sur la santé en prévention primaire","q":"Quels sont les bénéfices généraux de l'activité physique régulière en prévention primaire chez l'adulte ?","a":"<ul><li>Prévention de l'<strong>obésité</strong> (effet important chez l'enfant)</li><li>Prévention de la <strong>perte d'autonomie</strong> : sarcopénie, ostéoporose, déclin cognitif (diminution des incidences d'Alzheimer et de Parkinson)</li><li>Bénéfices psychologiques : diminution du stress, réappropriation positive du corps, développement d'un relationnel positif, soulagement des tensions, renforcement de l'humeur</li></ul>"},{"i":"5557c8e7fc4a","n":248,"o":"248-5","u":"Étiologies","t":"Connaître les principaux effets de l'activité physique et de la condition physique sur la santé en prévention primaire","q":"Décrivez la relation effet/dose de l'activité physique en prévention primaire.","a":"<p>La relation effet/dose suit une <strong>courbe curviligne</strong> : le gain est <strong>maximal</strong> lors du passage d'inactif à modérément actif (<strong>30 minutes, 5 fois par semaine</strong>).</p>"},{"i":"bc10b2b876f7","n":248,"o":"248-5","u":"Étiologies","t":"Connaître les principaux effets de l'activité physique et de la condition physique sur la santé en prévention primaire","q":"Quels sont les risques pour la santé associés à un faible niveau d'activité physique en prévention primaire ?","a":"<ul><li>Mortalité totale et cardiovasculaire (davantage liée à la quantité d'AP qu'à son intensité)</li><li>Morbidité coronarienne</li><li>Diabète de type 2 et HTA</li><li>Cancer</li><li>Prise de poids</li><li>Troubles psychiques : anxiété, dépression</li></ul>"},{"i":"45f669fb6661","n":248,"o":"248-6","u":"Étiologies","t":"Connaître les effets de l'alimentation sur la santé","q":"Quels sont les principaux facteurs nutritionnels contribuant à la mortalité liés à une mauvaise alimentation ?","a":"<p>Les principaux facteurs nutritionnels sont l'<strong>excès de sel</strong> et un <strong>apport insuffisant en fruits et légumes</strong>.</p>"},{"i":"735f4f5ef9c3","n":248,"o":"248-6","u":"Étiologies","t":"Connaître les effets de l'alimentation sur la santé","q":"Quels sont les facteurs de risque nutritionnels et protecteurs associés aux cancers ?","a":"<ul><li>Les <strong>facteurs de risque</strong> incluent l'<strong>alcool</strong>, la <strong>viande rouge</strong>, la <strong>charcuterie</strong> (en particulier pour le cancer colorectal), le <strong>surpoids/obésité</strong> et les <strong>produits conservés dans le sel</strong> (cancer de l'estomac).</li><li>Les <strong>facteurs protecteurs</strong> sont une <strong>activité physique régulière</strong> (pour le cancer colorectal, du sein, de l'endomètre), les <strong>fibres et céréales complètes</strong>, les <strong>produits laitiers</strong> (cancer colorectal), les <strong>légumes et fruits</strong> (cancers des Voies Aéro-Digestives Supérieures), le <strong>café</strong> (foie, endomètre) et l'<strong>allaitement</strong> (cancer du sein).</li></ul>"},{"i":"879bab0311d5","n":248,"o":"248-6","u":"Étiologies","t":"Connaître les effets de l'alimentation sur la santé","q":"Quel est le poids de la mauvaise alimentation sur la mortalité mondiale ?","a":"<p>La part de mortalité attribuable à une mauvaise alimentation est estimée à <strong>15 %</strong> dans le monde, soit environ <strong>11 millions de décès par an</strong>. Cela représente <strong>1 décès sur 5</strong>, principalement dû aux maladies cardiovasculaires, aux cancers et au diabète.</p>"},{"i":"93878ff299bf","n":248,"o":"248-6","u":"Étiologies","t":"Connaître les effets de l'alimentation sur la santé","q":"Quels sont les effets de l'alimentation sur les maladies métaboliques et cardiovasculaires ?","a":"<ul><li>Le <strong>sel</strong> est un déterminant majeur de la <strong>pression artérielle</strong>.</li><li>Un excès d'<strong>acides gras saturés</strong> entraîne une <strong>hypercholestérolémie</strong> (augmentation du LDLc).</li><li>La <strong>prise de poids</strong> (bilan énergétique positif) est favorisée par la sédentarité, les boissons sucrées, le fast-food et une alimentation de type occidental.</li><li>L'<strong>obésité</strong> est un facteur de risque majeur de syndrome métabolique, de diabète de type 2, de cancer et de pathologies ostéo-articulaires.</li></ul>"},{"i":"a61d412fef7f","n":248,"o":"248-6","u":"Étiologies","t":"Connaître les effets de l'alimentation sur la santé","q":"Comment l'alimentation peut-elle influencer d'autres pathologies chroniques ?","a":"<ul><li>Les facteurs nutritionnels peuvent jouer un rôle dans l'<strong>inflammation</strong>, par exemple dans la polyarthrite rhumatoïde.</li><li>Les <strong>vitamines, minéraux antioxydants et acides gras polyinsaturés</strong> sont associés à une diminution du déclin cognitif et de la maladie d'Alzheimer.</li><li>Une implication possible dans le déclenchement de la <strong>migraine</strong> est également envisagée.</li></ul>"},{"i":"0cdabb333d38","n":248,"o":"248-7","u":"Étiologies","t":"Connaître les effets de l'inactivité physique et de la sédentarité sur la santé","q":"Quelle est l'importance du fractionnement de la sédentarité en matière de prévention des risques pour la santé ?","a":"<p>Le <strong>fractionnement de la durée de sédentarité</strong> est très important. Interrompre régulièrement les périodes assises procure un <strong>bénéfice propre</strong>, qui est indépendant de la quantité totale d'activité physique pratiquée par ailleurs. Cela signifie que même pour les personnes actives, réduire les temps d'assise continue est protecteur.</p>"},{"i":"1c1dcb91f97d","n":248,"o":"248-7","u":"Étiologies","t":"Connaître les effets de l'inactivité physique et de la sédentarité sur la santé","q":"L'inactivité physique et la sédentarité sont-elles considérées comme des facteurs de risque indépendants ?","a":"<p>Oui, l'inactivité physique et la sédentarité sont des <strong>facteurs de risque indépendants</strong>. Leurs effets délétères sur la santé s'ajoutent à ceux d'autres facteurs comme une mauvaise alimentation.</p>"},{"i":"3cf84cc23138","n":248,"o":"248-7","u":"Étiologies","t":"Connaître les effets de l'inactivité physique et de la sédentarité sur la santé","q":"Quelles sont les principales conséquences d'une inactivité physique et d'une sédentarité prolongée sur la santé ?","a":"<p>L'inactivité physique et la sédentarité peuvent entraîner :</p><ul><li>Une augmentation de la <strong>prévalence du surpoids et de l'obésité</strong>.</li><li>Une augmentation de la <strong>mortalité</strong> toutes causes confondues.</li><li>Une augmentation du risque de <strong>diabète de type 2</strong> et de <strong>maladies cardiovasculaires</strong>.</li><li>Une <strong>déminéralisation osseuse</strong>, particulièrement chez le sujet âgé.</li><li>Une <strong>fonte musculaire et un risque de dénutrition</strong>, notamment en cas d'alitement prolongé.</li></ul>"}]};